glsl:
float sdf(vec3 pos) {
    float x = pos.x, y = pos.y, z = pos.z;
    const float R = 0.6, rm = 0.35, tube = 0.15;
    const float pi2 = 6.28318530;
    const float p = 2.0, q = 3.0;

    // Arc-length aware sampling: more samples where curvature is high
    // (2,3) knot has 3-fold symmetry + faster arc in XZ plane
    const int BASE_SAMPLES = 600;

    float best_d = 1e9;
    float best_t = 0.0;

    // Two-pass: coarse scan then local refinement
    for (int i = 0; i < BASE_SAMPLES; i++) {
        float t = pi2 * float(i) / float(BASE_SAMPLES);
        float ct3 = cos(q * t), st3 = sin(q * t);
        float ct2 = cos(p * t), st2 = sin(p * t);
        float rr = R + rm * ct3;
        float kx = rr * ct2;
        float ky = rr * st2;
        float kz = rm * st3;
        float d = sqrt((x-kx)*(x-kx) + (y-ky)*(y-ky) + (z-kz)*(z-kz));
        if (d < best_d) { best_d = d; best_t = t; }
    }

    // Local refinement with arc-length density correction
    float arc_dense = pi2 / (p * 200.0); // denser near curvature
    for (int i = -12; i <= 12; i++) {
        float t = best_t + float(i) * arc_dense;
        float ct3 = cos(q * t), st3 = sin(q * t);
        float ct2 = cos(p * t), st2 = sin(p * t);
        float rr = R + rm * ct3;
        float kx = rr * ct2;
        float ky = rr * st2;
        float kz = rm * st3;
        float d = sqrt((x-kx)*(x-kx) + (y-ky)*(y-ky) + (z-kz)*(z-kz));
        if (d < best_d) best_d = d;
    }

    return best_d - tube;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5*iResolution.xy) / iResolution.y;
    float t = iTime * 0.4 + 1.2;
    vec3 ro = vec3(3.5*cos(t), 0.8*3.5, 3.5*sin(t));
    vec3 ww = normalize(-ro);
    vec3 uu = normalize(cross(ww, vec3(0.0, 1.0, 0.0)));
    vec3 vv = cross(uu, ww);
    vec3 rd = normalize(uv.x*uu + uv.y*vv + 1.7*ww);

    float d = 0.001, max_d = 12.0;
    for (int i = 0; i < 96; i++) {
        float h = sdf(ro + d*rd);
        if (abs(h) < 0.0015*d || d > max_d) break;
        d += h * 0.75;
    }

    vec3 col = vec3(0.04, 0.02, 0.07);
    if (d < max_d) {
        vec3 p = ro + d*rd;
        float e = 0.001;
        vec3 n = normalize(vec3(
            sdf(p+vec3(e,0,0)) - sdf(p-vec3(e,0,0)),
            sdf(p+vec3(0,e,0)) - sdf(p-vec3(0,e,0)),
            sdf(p+vec3(0,0,e)) - sdf(p-vec3(0,0,e))
        ));
        vec3 ld = normalize(vec3(1.5, 2.0, -0.5));
        float diff = max(dot(n, ld), 0.0);
        float spec = pow(max(dot(reflect(-ld, n), -rd), 0.0), 48.0) * 0.7;
        col = vec3(0.15, 0.55, 0.85)*diff + spec + vec3(0.08, 0.04, 0.12)*(1.0-diff);
        col *= exp(-d * 0.12);
    }
    fragColor = vec4(pow(clamp(col, 0.0, 1.0), vec3(0.4545)), 1.0);
}
